
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mpwlyp1m_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mpwlyp1m", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.169572717513798e+00, -4.091766551886100e+00, -3.982811372528539e+00, -3.832026275330684e+00, -3.626860593225535e+00, -3.354406016401365e+00, -3.004917935358620e+00, -2.577982374428664e+00, -2.090023756708467e+00, -1.574807309273647e+00, -1.061997353305610e+00, -7.070829443871496e-01, -6.068780782572333e-01, -5.069394174094823e-01, -3.706255832516335e-01, -2.345478472565144e-01, -1.313539087051614e-01, -4.749774286561322e-02, -1.268937644699673e-03, -4.736528151039675e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


